// Заказуемы: весовые (unit «кг» — вес шаг 0,5, мин 1) и обычные фикс-цена без
// вариантов. Позиции с вариантами (напитки-форматы) пока не заказуемы (B4).
// Раки — отдельный конфигуратор (RakiDetail), тут не участвуют.
const orderable = (e: MenuEntry): boolean => e.unit === "кг" || !(e.variants && e.variants.length);
const cartItemOf = (e: MenuEntry) => {
  const weight = e.unit === "кг";
  return {
    key: e.name,
    label: e.name,
    unitPrice: e.price,
    step: weight ? 0.5 : 1,
    min: 1,
    unit: (weight ? "кг" : "шт") as "кг" | "шт",
  };
};

// Данные меню приходят пропсами (БД через getMenuForPage() или фолбэк на
// menu.ts). Секции «Раки» и «Напитки» собираются из этих данных в buildSections.
const DRINK_IDS = ["soft", "tea", "beer"];
const MENU_ORDER = [
  "crab",
  "raki",
  "starters",
  "shrimp",
  "salads",
  "hot",
  "soups",
  "mussels",
  "mains",
  "garnish",
  "vongole",
  "sauces",
  "desserts",
  "drinks",
];

type RakiData = {
  id: string;
  title: string;
  sizes: RakiSizeTier[];
  preparations: RakiPreparation[];
  footnotes: string[];
};

function buildSections(chapters: Chapter[], raki: RakiData) {
  // Раки — отдельная глава; вводим как секцию (размер → ₽/кг).
  const RAKI_SECTION = {
    id: "raki",
    title: "Раки",
    lede: undefined as string | undefined,
    origin: undefined as string | undefined,
    layout: "cards" as const,
    entries: raki.sizes.map((s): MenuEntry => ({
      name: `Раки · ${s.tier}`,
      price: s.price,
      unit: "кг",
      note: `${s.countPerKg} шт/кг`,
      signature: false,
      spicy: false,
      group: undefined as string | undefined,
    })),
  };
  // «Напитки» — UI-слияние soft+tea+beer в одну категорию с под-группами.
  // Контент дока НЕ трогаем: те же entries, пиву проставляем группу «Пиво».
  const DRINKS_SECTION = {
    id: "drinks",
    title: "Коллекция напитков",
    lede: undefined as string | undefined,
    origin: undefined as string | undefined,
    layout: "list" as const,
    entries: DRINK_IDS.flatMap((id): MenuEntry[] => {
      const ch = chapters.find((c) => c.id === id);
      if (!ch) return [];
      return ch.entries.map((e): MenuEntry => ({ ...e, group: e.group ?? "Пиво" }));
    }),
  };
  const RAW_SECTIONS = [
    RAKI_SECTION,
    ...chapters.filter((c) => !DRINK_IDS.includes(c.id)),
    DRINKS_SECTION,
  ];
  // Сначала — в заданном порядке MENU_ORDER; затем ДОБАВЛЯЕМ в конец любые главы
  // из БД, которых нет в MENU_ORDER (иначе новый/переименованный раздел молча
  // исчезал бы с витрины, оставаясь в боте и БД).
  const ordered = MENU_ORDER.map((id) => RAW_SECTIONS.find((section) => section.id === id)).filter(
    (section): section is NonNullable<typeof section> => Boolean(section),
  );
  const known = new Set(MENU_ORDER);
  const extra = RAW_SECTIONS.filter((section) => !known.has(section.id));
  return [...ordered, ...extra];
}

// Категории-списки (без фото): компактный текст, не карточки. Стиль теперь из БД
